pkg = [p for p in Path("/kaggle/input").rglob("run_two_gpus.py") if not p.name.startswith("._")][0].parent
shutil.copytree(pkg, W / "snap_compute", ignore=shutil.ignore_patterns("__pycache__", "._*"))
entries = []
for r in REQ:
    hits = [p for p in Path("/kaggle/input").rglob("manifest.json")
            if f"/{r['kernel']}/" in str(p) and str(p.parent).endswith(r["relpath"])]
    assert len(hits) == 1, (r, hits)
    dst = W / "audit" / r["kernel"] / r["relpath"]
    shutil.copytree(hits[0].parent, dst)
    entries.append({"job": r["job"], "path": str(dst), "config_hash": r["config_hash"]})
cfg = W / "C11.json"
cfg.write_text(json.dumps({"template_only": False, "seed": 20260914, "required_outputs": entries}, indent=1))
subprocess.check_call([sys.executable, str(W / "snap_compute" / "runs" / "C11.py"), "--config", str(cfg), "--out", str(W / "C11")])
res = json.load(open(W / "C11" / "result.json"))
print("[C11]", res["status"], len(res["checks"]), "checks passed", flush=True)
assert len(res["checks"]) == len(REQ)
shutil.rmtree(W / "audit"); shutil.rmtree(W / "snap_compute")
